from pathlib import Path

import pytest

from conftest import run_legacy_bus_testbench
from conftest import run_jal_direction_testbench
from serv_oracle.structure_contracts import (
    assert_legacy_bus_abi,
    assert_no_workspace_simulator_outputs,
)


TESTBENCH = Path(__file__).parent / "serv_oracle" / "serv_legacy_feature_tb.v"

@pytest.mark.core
def test_checkpoint_1_public_instruction_and_load_request_behavior(
    serv_candidate_repo, tmp_path
):
    output = run_legacy_bus_testbench(serv_candidate_repo, TESTBENCH, tmp_path, 0)
    assert "SERV_C1_DIRECTED_PASS" in output


@pytest.mark.core
def test_checkpoint_1_negative_jal_redirects_next_fetch(
    serv_candidate_repo, tmp_path
):
    run_jal_direction_testbench(serv_candidate_repo, tmp_path)


@pytest.mark.structure
def test_checkpoint_1_preserves_public_legacy_bus_abi(serv_candidate_repo, pytestconfig):
    assert_no_workspace_simulator_outputs(Path.cwd())
    checkpoint = pytestconfig.getoption("--checkpoint")
    checkpoint_number = int(checkpoint.rsplit("_", 1)[-1])
    if checkpoint_number >= 6:
        pytest.skip("checkpoint 6 replaces the legacy instruction/data buses with Wishbone")
    assert_legacy_bus_abi(serv_candidate_repo)


@pytest.mark.core
def test_checkpoint_1_pending_requests_remain_stable_under_backpressure(serv_candidate_repo, tmp_path):
    run_legacy_bus_testbench(serv_candidate_repo, TESTBENCH, tmp_path, 19)

